package com.aurax.operator.operator
import android.graphics.Rect
import android.text.InputType
import android.view.accessibility.AccessibilityNodeInfo
data class ScreenContext(val packageName:String,val windowTitle:String,val allText:String,val clickableElements:List<UiElement>,val hasPasswordField:Boolean,val hasSensitiveText:Boolean,val isPrivateBrowsing:Boolean)
object ScreenContextExtractor { fun extract(root:AccessibilityNodeInfo):ScreenContext{val texts=mutableListOf<String>();val elements=mutableListOf<UiElement>();var password=false;fun walk(node:AccessibilityNodeInfo){node.text?.toString()?.takeIf{it.isNotBlank()}?.let(texts::add);node.contentDescription?.toString()?.takeIf{it.isNotBlank()}?.let(texts::add);if((node.inputType and InputType.TYPE_TEXT_VARIATION_PASSWORD)!=0)password=true;if(node.isClickable||node.isEditable){val b=Rect().also(node::getBoundsInScreen);elements+=UiElement(node.text?.toString(),node.contentDescription?.toString(),node.viewIdResourceName,node.className?.toString(),b,node.isEditable,node.inputType,node.isClickable)};for(i in 0 until node.childCount)node.getChild(i)?.let(::walk)};walk(root);val joined=texts.joinToString(" | ");val privateBrowsing=joined.contains("incognito",true)||joined.contains("private browsing",true);return ScreenContext(root.packageName?.toString().orEmpty(),texts.firstOrNull().orEmpty(),joined,elements,password,AccessibilityGuardrails.isSensitiveText(joined),privateBrowsing)}}